#include <iostream>
#include <string>
#include <algorithm>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    std::string input;
    std::cin >> input;

    if (input.length() < 3) {
        std::cout << "No";
        return 0;
    }

    for (size_t i = 0; i <= input.length() - 3; ++i) {
        std::string sub = input.substr(i, 3);
        std::sort(sub.begin(), sub.end());
        if (sub == "ABC") {
            std::cout << "Yes";
            return 0;
        }
    }

    std::cout << "No";
    return 0;
}

